# %% [markdown]
# ## Step 9 — Build a Comparison Report
#
# Create a side-by-side comparison of how the two variants performed on this test case.

# %%
print("="*70)
print("  EVALUATION COMPARISON: Concise vs. Comprehensive")
print("="*70)
print(f"\nTest Case: {test_q}")
print(f"Category: {golden_qa[0]['category']}")

if 'scores_a' in dir() and 'scores_b' in dir():
    criteria = ['relevance', 'correctness', 'helpfulness', 'completeness']
    print(f"\n{'Criterion':<15} {'Variant A':<12} {'Variant B':<12} {'Δ':<8}")
    print("-" * 50)
    
    overall_a = []
    overall_b = []
    
    for crit in criteria:
        score_a = scores_a.get(crit, 0)
        score_b = scores_b.get(crit, 0)
        delta = score_b - score_a
        overall_a.append(score_a)
        overall_b.append(score_b)
        delta_str = f"+{delta}" if delta >= 0 else f"{delta}"
        print(f"{crit:<15} {score_a:<12} {score_b:<12} {delta_str:<8}")
    
    avg_a = sum(overall_a) / len(overall_a) if overall_a else 0
    avg_b = sum(overall_b) / len(overall_b) if overall_b else 0
    print("-" * 50)
    print(f"{'AVERAGE':<15} {avg_a:<12.2f} {avg_b:<12.2f} {(avg_b - avg_a):+.2f}")
    print("="*70)
else:
    print("\n⚠️ Could not build comparison (scores not available)")

# %% [markdown]
# ## Step 10 — Summary & Decision
#
# Analyze which variant is performing better overall.

# %%
if 'scores_a' in dir() and 'scores_b' in dir():
    print("\n📊 SUMMARY")
    print("-" * 50)
    
    overall_a = [scores_a.get(c, 0) for c in ['relevance', 'correctness', 'helpfulness', 'completeness']]
    overall_b = [scores_b.get(c, 0) for c in ['relevance', 'correctness', 'helpfulness', 'completeness']]
    
    avg_a = sum(overall_a) / len(overall_a) if overall_a else 0
    avg_b = sum(overall_b) / len(overall_b) if overall_b else 0
    
    if avg_b > avg_a:
        winner = "Variant B (Comprehensive)"
        margin = avg_b - avg_a
    elif avg_a > avg_b:
        winner = "Variant A (Concise)"
        margin = avg_a - avg_b
    else:
        winner = "TIE"
        margin = 0
    
    print(f"Winner: {winner}")
    if margin:
        print(f"Margin: +{margin:.2f} points")
    
    print(f"\nVariant A Avg: {avg_a:.2f}/5")
    print(f"Variant B Avg: {avg_b:.2f}/5")
    print("\nNext Step: Run both variants on all 10 golden test cases,")
    print("aggregate scores, and build confidence intervals to detect")
    print("statistically significant differences.")
else:
    print("Results not yet available.")

